 23→// CompactOptions provides metadata fields written to every output line.
 24→type CompactOptions struct {
 25→	Agent      string // e.g. "claude-code"
 26→	CLIVersion string // e.g. "0.42.0"
 27→	StartLine  int    // checkpoint_transcript_start (0 = no truncation)
 28→}
