374→// minimizeToolUseResult keeps only fields needed for replaying tool calls
375→// (type, file metadata, error, answers). Output text and other verbose
376→// fields are dropped to reduce transcript size.
377→func minimizeToolUseResult(raw json.RawMessage) json.RawMessage {
378→	var obj map[string]json.RawMessage
379→	if json.Unmarshal(raw, &obj) != nil {
380→		return raw
381→	}
382→
383→	return marshalOrdered(
384→		"type", obj["type"],
385→		"file", obj["file"],
386→		"error", obj["error"],
387→		"answers", obj["answers"],
