with open('cmd/entire/cli/transcript/testdata/opencode_full.jsonl') as f:
    data = json.load(f)

from datetime import datetime, timezone

def ms_to_ts(ms):
    dt = datetime.fromtimestamp(ms / 1000, tz=timezone.utc)
    # Match Go's RFC3339Nano - strip trailing zeros from fractional seconds
    s = dt.strftime('%Y-%m-%dT%H:%M:%S')
